import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百六十三章 进入荆棘丛的绵羊","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/163第一百六十三章 进入荆棘丛的绵羊.md","filePath":"meditation/巴利文大藏经/163第一百六十三章 进入荆棘丛的绵羊.md"}'),o={name:"meditation/巴利文大藏经/163第一百六十三章 进入荆棘丛的绵羊.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百六十三章-进入荆棘丛的绵羊" tabindex="-1">第一百六十三章 进入荆棘丛的绵羊 <a class="header-anchor" href="#第一百六十三章-进入荆棘丛的绵羊" aria-label="Permalink to &quot;第一百六十三章 进入荆棘丛的绵羊&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部17相应4经/长毛经(利得恭敬相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。</p><p>弟子们，就如同有一只满身长毛的绵羊，它走入了荆棘丛中，它会被无数的尖刺钩住、困住，这些尖刺会让它无法动弹。它也会被无数的尖刺刺伤流出血，让它自己身上血迹斑斑、体无完肤。困住它的荆棘丛会给它带来不幸和灾祸，它受伤流出的血会遭来凶狠的豺狼、豹子等等猛兽，这只绵羊将会由此受害。</p><p>弟子们，同样的道理，中午的时候，有一位出家人，他穿上法衣，拿着饭钵到乡村或城镇中化缘饭食，如果他贪图美妙好吃的饮食，就会被美妙好吃的饮食钩住、困住。他的内心也将会被贪图美妙好吃饮食的尖刺刺的血迹斑斑、体无完肤。贪吃的欲望将会给他带来不幸和灾祸，他将会失去内心清净的境界，他将会为美妙好吃的饮食胡思乱想，他将会沉浸、沉溺在贪吃欲望的海洋中不得解脱，他将会由此产生无数的烦恼和痛苦。</p><p>所以，弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。</p><p>世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
